// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts) public {
        // keep the block number and timestamp in the admissible domain
        uint256 bn = bound(blockNum, 1, type(uint48).max);
        uint256 t = bound(ts, block.timestamp + 1, type(uint64).max - 1);

        vm.roll(bn);
        vm.warp(t);

        address actor = address(0xABCD);
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // General rule: after a successful call, the contract was drained exactly when block.number % 15 == 0.
        assertTrue((address(c).balance == 0) == (bn % 15 == 0));
    }
}
